import { test, expect, Page } from "@playwright/test";
import path from "path";
import fs from "fs";

/**
 * End-to-end verification of the Resume Upload workflow (real browser, real server, real files).
 * Fixtures are generated by scratch/make_upload_fixtures.py.
 * Verified stages:
 *  A. Upload button click opens the native file picker via filechooser event.
 *  B. File selection / change event reaches React state and clears stale state.
 *  C. Upload HTTP request is sent with proper payload (base64 JSON to /api/resume/extract-*).
 *  D. Server validates format, magic bytes, and size limits.
 *  E. Document extraction succeeds (PDF text, DOCX text).
 *  F. Resume Intelligence profile is updated in React and localStorage (never stale).
 */
const FIX = (name: string) => path.resolve(process.cwd(), "scratch", "upload_fixtures", name);

async function openResumeTab(page: Page) {
  await page.goto("/?tab=resume");
  await expect(page.getByRole("heading", { name: "Resume Intelligence", level: 2 })).toBeVisible({ timeout: 20000 });
  // Start from clean slate so any profile we see afterwards is strictly from this upload
  await page.evaluate(() => {
    localStorage.removeItem("yatra_parse_result");
    localStorage.removeItem("yatra_candidate_profile");
  });
  await page.reload();
  await expect(page.getByRole("heading", { name: "Resume Intelligence", level: 2 })).toBeVisible({ timeout: 20000 });
}

function trackApi(page: Page) {
  const calls: { url: string; status: number }[] = [];
  page.on("response", (r) => {
    if (r.url().includes("/api/resume/")) {
      calls.push({ url: new URL(r.url()).pathname, status: r.status() });
    }
  });
  return calls;
}

test.describe("Resume upload workflow", () => {
  test.setTimeout(120000);

  test("Stage A: Clicking the upload button opens the browser file picker", async ({ page }) => {
    await openResumeTab(page);

    // Verify accept attribute contains advertised formats
    const acceptAttr = await page.locator('input[type="file"]').getAttribute("accept");
    expect(acceptAttr).toContain(".pdf");
    expect(acceptAttr).toContain(".docx");

    // Clicking 'Upload Resume' button triggers the file chooser
    const [fileChooser] = await Promise.all([
      page.waitForEvent("filechooser", { timeout: 10000 }),
      page.getByRole("button", { name: "Upload Resume" }).click(),
    ]);
    expect(fileChooser).toBeDefined();
    expect(fileChooser.isMultiple()).toBeFalsy();
  });

  test("Stages B-F: Valid PDF reaches server, extracts text, and populates exact extracted candidate details in UI", async ({ page }) => {
    const calls = trackApi(page);
    await openResumeTab(page);

    // Upload real PDF fixture
    await page.setInputFiles('input[type="file"]', FIX("valid_resume.pdf"));

    // Verify extraction HTTP request was sent and succeeded
    await expect.poll(() => calls.some((c) => c.url === "/api/resume/extract-pdf"), { timeout: 15000 }).toBeTruthy();
    expect(calls.find((c) => c.url === "/api/resume/extract-pdf")!.status).toBe(200);

    // Verify parser pipeline was invoked
    await expect.poll(() => calls.some((c) => c.url === "/api/resume/parse"), { timeout: 75000 }).toBeTruthy();
    expect(calls.find((c) => c.url === "/api/resume/parse")!.status).toBe(200);

    // Verify profile state is updated in localStorage
    await expect.poll(async () => page.evaluate(() => localStorage.getItem("yatra_parse_result")), { timeout: 90000 }).not.toBeNull();

    // Verify parsed data in localStorage contains candidate name or skills from fixture
    const parseResultStr = await page.evaluate(() => localStorage.getItem("yatra_parse_result"));
    expect(parseResultStr).toBeTruthy();
    const parseResult = JSON.parse(parseResultStr!);
    expect(Array.isArray(parseResult.skills)).toBeTruthy();
    expect(parseResult.skills.length).toBeGreaterThan(0);

    // Verify the UI actually renders the exact synthetic candidate details
    await expect(page.getByText("Aarav Mehta").first()).toBeVisible({ timeout: 10000 });
    await expect(page.getByText("aarav.mehta@example.com").first()).toBeVisible({ timeout: 10000 });

    console.log("PDF extraction and parse verified. Skills found:", parseResult.skills.slice(0, 5));
  });

  test("Stages B-F: Valid DOCX reaches server, extracts text, and populates exact extracted candidate details in UI", async ({ page }) => {
    const calls = trackApi(page);
    await openResumeTab(page);

    // Upload real DOCX fixture
    await page.setInputFiles('input[type="file"]', FIX("valid_resume.docx"));

    // Verify extract-docx HTTP request succeeded
    await expect.poll(() => calls.some((c) => c.url === "/api/resume/extract-docx"), { timeout: 15000 }).toBeTruthy();
    expect(calls.find((c) => c.url === "/api/resume/extract-docx")!.status).toBe(200);

    // Verify parser pipeline was invoked
    await expect.poll(() => calls.some((c) => c.url === "/api/resume/parse"), { timeout: 75000 }).toBeTruthy();
    expect(calls.find((c) => c.url === "/api/resume/parse")!.status).toBe(200);

    // Verify profile state updated
    await expect.poll(async () => page.evaluate(() => localStorage.getItem("yatra_parse_result")), { timeout: 90000 }).not.toBeNull();
    const parseResultStr = await page.evaluate(() => localStorage.getItem("yatra_parse_result"));
    const parseResult = JSON.parse(parseResultStr!);
    expect(parseResult.skills.length).toBeGreaterThan(0);

    // Verify the UI actually renders the exact synthetic candidate details
    await expect(page.getByText("Aarav Mehta").first()).toBeVisible({ timeout: 10000 });
    await expect(page.getByText("aarav.mehta@example.com").first()).toBeVisible({ timeout: 10000 });

    console.log("DOCX extraction and parse verified. Skills found:", parseResult.skills.slice(0, 5));
  });

  test("Stage D: Fake PDF (text file renamed .pdf) is rejected with actionable error and stores no profile", async ({ page }) => {
    await openResumeTab(page);

    await page.setInputFiles('input[type="file"]', FIX("fake_resume.pdf"));

    // Actionable error message displayed
    await expect(page.getByText(/not a valid PDF/i).first()).toBeVisible({ timeout: 10000 });

    // No profile data stored or retained
    expect(await page.evaluate(() => localStorage.getItem("yatra_parse_result"))).toBeNull();
    expect(await page.evaluate(() => localStorage.getItem("yatra_candidate_profile"))).toBeNull();
  });

  test("Stage D: Unsupported file type (.exe) is rejected with actionable error and stores no profile", async ({ page }) => {
    await openResumeTab(page);

    await page.setInputFiles('input[type="file"]', FIX("bad_format.exe"));

    // Actionable error message displayed
    await expect(page.getByText(/Unsupported file format/i).first()).toBeVisible({ timeout: 10000 });

    // No profile data stored or retained
    expect(await page.evaluate(() => localStorage.getItem("yatra_parse_result"))).toBeNull();
    expect(await page.evaluate(() => localStorage.getItem("yatra_candidate_profile"))).toBeNull();
  });

  test("Stale data prevention: An invalid upload after a successful upload immediately clears the previous profile", async ({ page }) => {
    await openResumeTab(page);

    // 1. Upload valid DOCX -> profile is displayed
    await page.setInputFiles('input[type="file"]', FIX("valid_resume.docx"));
    await expect.poll(async () => page.evaluate(() => localStorage.getItem("yatra_parse_result")), { timeout: 90000 }).not.toBeNull();
    await expect(page.getByText("Aarav Mehta").first()).toBeVisible({ timeout: 10000 });

    // 2. Upload invalid fake PDF -> previous profile must be wiped immediately
    await page.setInputFiles('input[type="file"]', FIX("fake_resume.pdf"));

    // Error is shown
    await expect(page.getByText(/not a valid PDF/i).first()).toBeVisible({ timeout: 10000 });

    // Stale profile is completely gone from DOM and localStorage
    await expect(page.getByText("Aarav Mehta")).toHaveCount(0);
    expect(await page.evaluate(() => localStorage.getItem("yatra_parse_result"))).toBeNull();
    expect(await page.evaluate(() => localStorage.getItem("yatra_candidate_profile"))).toBeNull();
  });

  test("Drag-and-Drop: Dropping a valid PDF into the dropzone triggers extraction and profile update", async ({ page }) => {
    await openResumeTab(page);

    const buffer = fs.readFileSync(FIX("valid_resume.pdf"));
    const dataTransfer = await page.evaluateHandle((data) => {
      const dt = new DataTransfer();
      const file = new File([new Uint8Array(data.bytes)], "valid_resume.pdf", { type: "application/pdf" });
      dt.items.add(file);
      return dt;
    }, { bytes: Array.from(buffer) });

    await page.dispatchEvent(".border-dashed", "drop", { dataTransfer });

    // Verify profile state updated in UI and storage
    await expect.poll(async () => page.evaluate(() => localStorage.getItem("yatra_parse_result")), { timeout: 90000 }).not.toBeNull();
    const parseResultStr = await page.evaluate(() => localStorage.getItem("yatra_parse_result"));
    const parseResult = JSON.parse(parseResultStr!);
    expect(parseResult.skills.length).toBeGreaterThan(0);
    await expect(page.getByText("Aarav Mehta").first()).toBeVisible({ timeout: 10000 });

    console.log("Drag-and-drop upload verified. Skills found:", parseResult.skills.slice(0, 5));
  });
});
